package vault

import (
	"encoding/json"
	"fmt"
	"os"
	"testing"
)

// TestSlugify asserts parity with the values generated by the Python reference
// implementation, read from the committed corpus.
func TestSlugify(t *testing.T) {
	data, err := os.ReadFile("../../testdata/slug_corpus.json")
	if err != nil {
		t.Fatalf("read corpus: %v", err)
	}
	var cases []struct {
		Title string `json:"title"`
		Slug  string `json:"slug"`
	}
	if err := json.Unmarshal(data, &cases); err != nil {
		t.Fatalf("parse corpus: %v", err)
	}
	if len(cases) != 15 {
		t.Fatalf("corpus has %d entries, want 15", len(cases))
	}

	for i, c := range cases {
		t.Run(fmt.Sprintf("%02d/%s", i, c.Title), func(t *testing.T) {
			if got := slugify(c.Title); got != c.Slug {
				t.Errorf("slugify(%q) = %q, want %q", c.Title, got, c.Slug)
			}
		})
	}
}
